/**
 * Migration 0005_calendar_feed (plan m9 P3, P13, P14; M9-T01): the `calendar_feed_tokens` table, GENERATED by drizzle-kit
 * from `apps/api/src/modules/calendar/schema.ts`. Applied to a scratch `file:` database through `@libsql/client` (never
 * `bun:sqlite`, a newer SQLite), in the shape of `db-calendar-migration.test.ts`: the journal entry, the columns, every
 * CHECK with one valid and one refused row, the two unique indexes, and the cascades from the household and the user.
 */
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterAll, beforeAll, describe, expect, test } from "bun:test";
import { type Client, type InValue, createClient } from "@libsql/client";
import { drizzle } from "drizzle-orm/libsql";
import { migrate } from "drizzle-orm/libsql/migrator";
import { MIGRATIONS_FOLDER } from "../src/db/migrate.ts";

const dir = mkdtempSync(join(tmpdir(), "toon-calendar-feed-migration-"));
let client: Client;

beforeAll(async () => {
  client = createClient({ url: `file:${join(dir, "feed.db")}` });
  await client.execute("PRAGMA foreign_keys = ON");
  await migrate(drizzle(client), { migrationsFolder: MIGRATIONS_FOLDER });
  await client.execute(
    "INSERT INTO users (id, email, name, password_hash, created_at, updated_at) VALUES ('u1', 'a@toon.test', 'A', 'h', 1, 1), ('u2', 'b@toon.test', 'B', 'h', 1, 1)",
  );
  await client.execute(
    "INSERT INTO households (id, name, created_by, created_at, updated_at) VALUES ('h1', 'Familie', 'u1', 1, 1), ('h2', 'WG', 'u2', 1, 1)",
  );
});

afterAll(() => {
  client.close();
  rmSync(dir, { recursive: true, force: true });
});

async function scalar(sql: string, args: InValue[] = []): Promise<unknown> {
  return (await client.execute({ sql, args })).rows[0]?.[0];
}

let serial = 0;

/** A 64-character hex string unique per call (the shape of a SHA-256 hex digest). */
function hash(): string {
  serial += 1;
  return serial.toString(16).padStart(64, "0");
}

/** Inserts a feed token with valid defaults overridden by `fields`; resolves the id. */
async function insertToken(fields: Record<string, InValue> = {}): Promise<string> {
  const row: Record<string, InValue> = {
    id: `t${serial + 1}`,
    household_id: "h1",
    user_id: "u1",
    token_hash: hash(),
    scope: "all",
    created_at: 1,
    ...fields,
  };
  const columns = Object.keys(row);
  await client.execute({
    sql: `INSERT INTO calendar_feed_tokens (${columns.join(", ")}) VALUES (${columns.map(() => "?").join(", ")})`,
    args: columns.map((column) => row[column] ?? null),
  });
  return String(row.id);
}

async function count(where = "1 = 1", args: InValue[] = []): Promise<number> {
  return Number(await scalar(`SELECT count(*) FROM calendar_feed_tokens WHERE ${where}`, args));
}

describe("migration 0005_calendar_feed", () => {
  test("it is the journal's sixth entry and creates calendar_feed_tokens with its indexes", async () => {
    const journal = JSON.parse(readFileSync(join(MIGRATIONS_FOLDER, "meta/_journal.json"), "utf8")) as { entries: Array<{ tag: string }> };
    expect(journal.entries.map((entry) => entry.tag)[5]).toBe("0005_calendar_feed");
    const columns = (await client.execute("PRAGMA table_info(calendar_feed_tokens)")).rows.map((row) => [
      String(row.name),
      String(row.type),
      Number(row.notnull),
    ]);
    expect(columns).toEqual([
      ["id", "TEXT", 1],
      ["household_id", "TEXT", 1],
      ["user_id", "TEXT", 1],
      ["token_hash", "TEXT", 1],
      ["scope", "TEXT", 1],
      ["created_at", "INTEGER", 1],
      ["last_used_at", "INTEGER", 0],
    ]);
    const indexes = (
      await client.execute(
        "SELECT name FROM sqlite_master WHERE type = 'index' AND tbl_name = 'calendar_feed_tokens' AND name NOT LIKE 'sqlite_%' ORDER BY name",
      )
    ).rows.map((row) => String(row.name));
    expect(indexes).toEqual([
      "calendar_feed_tokens_household_user_uidx",
      "calendar_feed_tokens_token_hash_uidx",
      "calendar_feed_tokens_user_idx",
    ]);
    expect(await scalar("PRAGMA foreign_key_check")).toBeUndefined();
  });

  test("scope CHECK: all or mine", async () => {
    await insertToken({ household_id: "h1", user_id: "u1", scope: "mine" });
    await expect(insertToken({ household_id: "h2", user_id: "u1", scope: "everyone" })).rejects.toThrow("calendar_feed_tokens_scope");
    await client.execute("DELETE FROM calendar_feed_tokens");
  });

  test("token_hash CHECK: exactly 64 characters", async () => {
    await expect(insertToken({ token_hash: "abc" })).rejects.toThrow("calendar_feed_tokens_token_hash_format");
    await expect(insertToken({ token_hash: `${hash()}0` })).rejects.toThrow("calendar_feed_tokens_token_hash_format");
    await insertToken({ token_hash: hash() });
    await client.execute("DELETE FROM calendar_feed_tokens");
  });

  test("one link per (household, user); a token hash is unique across households", async () => {
    const shared = hash();
    await insertToken({ household_id: "h1", user_id: "u1", token_hash: shared });
    await expect(insertToken({ household_id: "h1", user_id: "u1" })).rejects.toThrow("UNIQUE");
    await expect(insertToken({ household_id: "h2", user_id: "u2", token_hash: shared })).rejects.toThrow("UNIQUE");
    await insertToken({ household_id: "h2", user_id: "u1" });
    await insertToken({ household_id: "h1", user_id: "u2" });
    expect(await count()).toBe(3);
    await client.execute("DELETE FROM calendar_feed_tokens");
  });

  test("a foreign key to an unknown household or user is refused", async () => {
    await expect(insertToken({ household_id: "nope" })).rejects.toThrow("FOREIGN KEY");
    await expect(insertToken({ user_id: "nope" })).rejects.toThrow("FOREIGN KEY");
  });

  test("the row cascades with its household and with its user", async () => {
    await insertToken({ household_id: "h1", user_id: "u1" });
    await insertToken({ household_id: "h2", user_id: "u1" });
    await insertToken({ household_id: "h2", user_id: "u2", last_used_at: 5 });
    expect(await scalar("SELECT last_used_at FROM calendar_feed_tokens WHERE household_id = 'h2' AND user_id = 'u2'")).toBe(5);

    await client.execute("DELETE FROM households WHERE id = 'h1'");
    expect(await count("household_id = 'h1'")).toBe(0);
    expect(await count()).toBe(2);

    await client.execute("UPDATE households SET created_by = 'u2' WHERE id = 'h2'");
    await client.execute("DELETE FROM users WHERE id = 'u1'");
    expect(await count("user_id = 'u1'")).toBe(0);
    expect(await count()).toBe(1);
  });
});
